while True:
    resp = client.messages.create(model=MODEL, messages=messages, tools=tools)
    messages.append({"role": "assistant", "content": resp.content})

    if resp.stop_reason == "end_turn":
        return resp.text          # model is done -> stop on the SIGNAL, not on phrases

    if resp.stop_reason == "tool_use":
        results = []
        for block in resp.tool_use_blocks():
            output = run_tool(block.name, block.input)
            results.append({"type": "tool_result",
                            "tool_use_id": block.id, "content": output})
        messages.append({"role": "user", "content": results})   # feed back, then iterate

