class PrerequisiteGate:
    """Block process_refund until get_customer has VERIFIED the customer."""
    def __init__(self):
        self.verified_customer_id = None

    def record_tool_result(self, name, result):
        if name == "get_customer" and result.get("verified") and result.get("customer_id"):
            self.verified_customer_id = result["customer_id"]

    def check(self, tool):
        if tool == "process_refund":
            return self.verified_customer_id is not None   # gate, not a hope
        return True

def intercept_tool_call(name, tool_input, refund_limit=500):
    """Runs in CODE on every call -> deterministic, unlike a prompt rule."""
    if name == "process_refund" and tool_input.get("amount", 0) > refund_limit:
        return {"action": "block",
                "redirect": "escalate_to_human",
                "reason": f"Refund over ${refund_limit} requires a human."}
    return {"action": "allow"}

