@model_validator(mode="after")
def reconcile(self):
    calc = round(sum(i.amount for i in self.line_items), 2)
    if abs(calc - self.stated_total) > 0.01:
        raise ValueError(
            f"stated_total ({self.stated_total}) != sum of line items ({calc}) "
            "[detected_pattern=stated_total_mismatch]")
    return self

