def submission_interval(sla_hours, batch_window_hours=24):
    interval = sla_hours - batch_window_hours
    if interval <= 0:
        raise ValueError("SLA must exceed the 24h batch window")
    return interval   # e.g. sla=30 -> submit at least every 6h

