def decide(case: dict) -> str:
    # Honor an explicit human request immediately, without investigating.
    if case["asked_for_human"]:
        return "ESCALATE"
    # Policy is silent / ambiguous / has a gap on this request.
    if case["policy_state"] in {"gap", "silent", "ambiguous"}:
        return "ESCALATE"
    # Cannot make meaningful progress (e.g. backend down) -> hand off.
    if not case["can_make_progress"]:
        return "ESCALATE"
    # Multiple records match -> get another identifier, do not guess.
    if case["match_count"] > 1:
        return "ASK_CLARIFY"
    # Straightforward and within capability. Sentiment is irrelevant.
    return "RESOLVE"

