def overall_confidence(extraction: dict) -> float:
    confs = extraction["confidences"]  # e.g. {"vendor": 0.99, "total": 0.88}
    return min(confs.values())  # a chain is only as strong as its weakest field

def route(extraction: dict, threshold: float) -> str:
    if extraction.get("source_contradictory"):
        return "REVIEW"  # ambiguity overrides a high score
    return "REVIEW" if overall_confidence(extraction) < threshold else "AUTO_APPROVE"

